examples.template:
MonarchButton({{trigger}}) { previewed = source }
    .onAppear { previewed = source }
    .sheet(item: $previewed) { source in
        MonarchAiSourcePreview(
            source,
            quote: {{quote}},
            content: {{content}}
        )
    }

examples.code:
MonarchButton("Preview source") { previewed = source }
    .onAppear { previewed = source }
    .sheet(item: $previewed) { source in
        MonarchAiSourcePreview(
            source,
            quote: "Requests are answered within two working days.",
            content: "Welcome to the team. This handbook explains how we work together.\n\nRequests are answered within two working days. Urgent issues go to the on-call queue, which answers within two hours.\n\nEvery request gets an owner. The owner keeps the requester up to date until it is closed."
        )
    }
